# Print the notice of every Wayland protocol a build compiled in. wayland-scanner copies
# each protocol's copyright into the code it generates, as the comment after its
# "Generated by" line, and that code is linked into the binary. A protocol generated
# for more than one target is printed once.
#
# Usage: scripts/protocol_notices.sh BUILD_DIR
set -euo pipefail

dir="${1:?usage: $0 BUILD_DIR}"
mapfile -t generated < <(grep -rl --include='*.c' '^/\* Generated by wayland-scanner' "$dir" | sort)
[ "${#generated[@]}" -gt 0 ] || { echo "ERROR: no wayland-scanner code in $dir" >&2; exit 1; }
awk 'FNR == 1 { name = FILENAME; sub(/.*\//, "", name); sub(/\.c$/, "", name); skip = seen[name]++ }
  FNR == 3 && /^\/\*/ && !skip { p = 1; printf "## %s\n\n", name; sub(/^\/\* ?/, ""); if ($0 == "") next }
  p && $0 == " */" { p = 0; print ""; next }
  p { sub(/^ \*( |$)/, ""); print }' "${generated[@]}"
